10|// Two audio elements with equal-power crossfades. Volume lives in a
11|// ref, so the slider never re-runs the track effect or touches src.
12|// Nothing plays before the first user press. Reduced motion only
13|// affects visuals; the audio fade always runs its full length.
14|export function Player({
15|  track,
16|  replayNonce,
17|  fadeSec,
18|  canPrev,
19|  onPrev,
20|  canSkip,
21|  onSkip,
22|  volume,
23|  muted,
24|  onVolumeChange,
25|  onMutedChange,
26|  styles,
27|  styleId,
28|  onStyleChange,
29|  onEnded,
30|  playlistOn,
31|  playlistLabel,
32|  onTogglePlaylist,
33|  controlsDisabled,
34|}: {
35|  track: Track | null;
36|  replayNonce: number;
37|  fadeSec: number;
38|  canPrev: boolean;
39|  onPrev: () => void;
40|  canSkip: boolean;
41|  onSkip: () => void;
42|  volume: number;
43|  muted: boolean;
44|  onVolumeChange: (volume: number) => void;
45|  onMutedChange: (muted: boolean) => void;
46|  styles: StyleInfo[];
47|  styleId: string | null;
48|  onStyleChange: (style: string) => void;
49|  onEnded: (trackId: string) => void;
50|  playlistOn: boolean;
51|  playlistLabel: string | null;
52|  onTogglePlaylist: () => void;
53|  controlsDisabled: boolean;
54|}) {
55|  const firstRef = useRef<HTMLAudioElement | null>(null);
56|  const secondRef = useRef<HTMLAudioElement | null>(null);
57|  const audibleRef = useRef(0);
58|  const levelRef = useRef<[number, number]>([1, 0]);
59|  const gainRef = useRef<[number, number]>([0, 0]);
60|  const segmentEndRef = useRef<string | null>(null);
61|  // Slider value and mute live in the reader (persisted prefs); refs
62|  // mirror the props so the engine never re-runs on volume moves.
63|  const volumeRef = useRef(volume);
64|  volumeRef.current = volume;
65|  const mutedRef = useRef(muted);
66|  mutedRef.current = muted;
67|  const fadeRef = useRef<number | null>(null);
68|  const loopArmedRef = useRef<string | null>(null);
69|  const trackRef = useRef<Track | null>(track);
70|  trackRef.current = track;
71|  const fadeSecRef = useRef(fadeSec);
72|  fadeSecRef.current = fadeSec;
73|  const onEndedRef = useRef(onEnded);
74|  onEndedRef.current = onEnded;
75|  const playingRef = useRef(false);
76|  const startedRef = useRef(false);
77|  const firstPlayRef = useRef(true);
78|
79|  // Scheduler fade when set, else the config default; never 0 mid session.
80|  function loopFadeSec() {
81|    return fadeSecRef.current > 0 ? fadeSecRef.current : MUSIC_CONFIG.crossfadeSec;
82|  }
83|  const [started, setStarted] = useState(false);
84|  const [playing, setPlaying] = useState(false);
85|  const requestPlayRef = useRef((_: Track, __: number) => {});
86|
87|  const [reducedMotion, setReducedMotion] = useState(
88|    () =>
89|      typeof window !== "undefined" &&
90|      !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches,
91|  );
92|
93|  useEffect(() => {
94|    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
95|    if (!query) return;
96|    const onChange = (event: MediaQueryListEvent) => setReducedMotion(event.matches);
97|    query.addEventListener("change", onChange);
98|    return () => query.removeEventListener("change", onChange);
99|  }, []);
100|
101|  function applyLevels() {
102|    const els = [firstRef.current, secondRef.current];
103|    const audible = mutedRef.current ? 0 : volumeRef.current;
104|    els.forEach((el, i) => {
105|      if (el)
106|        el.volume = gainVolume(
107|          levelRef.current[i] ?? 0,
108|          audible,
109|          gainRef.current[i] ?? 0,
110|        );
111|    });
112|  }
113|
114|  function cancelFade() {
115|    if (fadeRef.current !== null) {
116|      cancelAnimationFrame(fadeRef.current);
117|      fadeRef.current = null;
118|    }
119|  }
120|
121|  // Assigned each render so handlers always see fresh refs. Fades from
122|  // the currently louder element to the newest track; a mid-fade request
123|  // cancels the pending fade and starts from current levels.
124|  requestPlayRef.current = (next: Track, durSec: number) => {
125|    const els = [firstRef.current, secondRef.current];
126|    const srcIdx = (levelRef.current[0] ?? 0) >= (levelRef.current[1] ?? 0) ? 0 : 1;
127|    const dstIdx = 1 - srcIdx;
128|    const srcEl = els[srcIdx];
129|    const dst = els[dstIdx];
130|    if (!srcEl || !dst) return;
131|    cancelFade();
132|    if (trackRef.current?.id !== next.id) loopArmedRef.current = null;
133|    trackRef.current = next;
134|    segmentEndRef.current = null;
135|    gainRef.current[dstIdx] = next.gainDb ?? 0;
136|    dst.src = next.src;
137|    dst.onloadedmetadata = () => {
138|      if (next.startSec > 0 && Number.isFinite(dst.duration) && next.startSec < dst.duration) {
139|        try {
140|          dst.currentTime = next.startSec;
141|        } catch {
142|          // Past the end; leave playback at zero.
143|        }
144|      }
145|    };
146|    if (!playingRef.current || durSec <= 0) {
147|      levelRef.current = [0, 0];
148|      levelRef.current[dstIdx] = 1;
149|      audibleRef.current = dstIdx;
150|      srcEl.pause();
151|      applyLevels();
152|      if (playingRef.current) void dst.play().catch(() => undefined);
153|      return;
154|    }
155|    if (playingRef.current) void dst.play().catch(() => undefined);
156|    const startSrc = levelRef.current[srcIdx] ?? 0;
157|    const startDst = levelRef.current[dstIdx] ?? 0;
158|    let t0 = performance.now();
159|    let prev = t0;
160|    const tick = (now: number) => {
161|      // Pause freezes the fade; resume continues from the frozen point.
162|      if (!playingRef.current) {
163|        t0 += now - prev;
164|        prev = now;
165|        fadeRef.current = requestAnimationFrame(tick);
166|        return;
167|      }
168|      prev = now;
169|      const t = Math.min(1, (now - t0) / (durSec * 1000));
170|      levelRef.current[srcIdx] = startSrc * Math.cos((t * Math.PI) / 2);
171|      levelRef.current[dstIdx] = startDst + (1 - startDst) * Math.sin((t * Math.PI) / 2);
172|      applyLevels();
173|      if (t < 1) {
174|        fadeRef.current = requestAnimationFrame(tick);
175|        return;
176|      }
177|      fadeRef.current = null;
178|      levelRef.current[srcIdx] = 0;
179|      levelRef.current[dstIdx] = 1;
180|      audibleRef.current = dstIdx;
181|      applyLevels();
182|      srcEl.pause();
183|    };
184|    fadeRef.current = requestAnimationFrame(tick);
185|  };
186|
187|  const trackId = track?.id ?? null;
188|  useEffect(() => {
189|    const next = trackRef.current;
190|    if (!started || !next) {
191|      // Before the first press, swaps only change src.
192|      if (!started && next) {
193|        const el = [firstRef.current, secondRef.current][audibleRef.current];
194|        if (el && !el.src.endsWith(next.src)) el.src = next.src;
195|        gainRef.current[audibleRef.current] = next.gainDb ?? 0;
196|        applyLevels();
197|      }
198|      return;
199|    }
200|    // The single start path: fade 0 on the very first press. replayNonce
201|    // re-cues the same track (one-track playlist wrap); nothing else is a dep
202|    // so volume, pause/play, and re-renders never restart the track.
203|    const dur = firstPlayRef.current ? 0 : fadeSecRef.current;
204|    firstPlayRef.current = false;
205|    requestPlayRef.current(next, dur);
206|  }, [started, trackId, replayNonce]);
207|
208|  useEffect(() => cancelFade, []);
209|
210|  function handleTimeUpdate(index: number, el: HTMLAudioElement) {
211|    const next = trackRef.current;
212|    if (!next || index !== audibleRef.current) return;
213|    const end = effectiveEnd(next.endSec, el.duration);
214|    if (!Number.isFinite(end)) return;
215|    // A non-looping or playlist track ends at the segment end, where the
216|    // media may keep playing, so fire the ended path once per play.
217|    if (!next.loop || playlistOn) {
218|      if (el.currentTime >= end && segmentEndRef.current !== next.id) {
219|        segmentEndRef.current = next.id;
220|        onEndedRef.current(next.id);
221|      }
222|      return;
223|    }
224|    const fade = loopFadeSec();
225|    if (end <= fade * 2) return;
226|    const remain = end - el.currentTime;
227|    if (remain <= fade && loopArmedRef.current !== next.id) {
228|      loopArmedRef.current = next.id;
229|      requestPlayRef.current(next, fade);
230|    } else if (remain > fade + 1) {
231|      loopArmedRef.current = null;
232|    }
233|  }
234|
235|  function handleEnded(index: number) {
236|    const els = [firstRef.current, secondRef.current];
237|    // An element that ends while a fade is running is the one fading out.
238|    if (index !== audibleRef.current || fadeRef.current !== null) {
239|      els[index]?.pause();
240|      return;
241|    }
242|    const next = trackRef.current;
243|    if (!next || segmentEndRef.current === next.id) return;
244|    if (next.loop && !playlistOn) {
245|      requestPlayRef.current(next, loopFadeSec());
246|      return;
247|    }
248|    segmentEndRef.current = next.id;
249|    onEndedRef.current(next.id);
250|  }
251|
252|  function toggle() {
253|    const both = [firstRef.current, secondRef.current];
254|    if (!startedRef.current) {
255|      startedRef.current = true;
256|      setStarted(true);
257|      playingRef.current = true;
258|      setPlaying(true);
259|      return;
260|    }
261|    if (playingRef.current) {
262|      for (const el of both) el?.pause();
263|      playingRef.current = false;
264|      setPlaying(false);
265|      return;
266|    }
267|    playingRef.current = true;
268|    setPlaying(true);
269|    let heard = false;
270|    both.forEach((el, i) => {
271|      if (el && (levelRef.current[i] ?? 0) > 0.02) {
272|        heard = true;
273|        void el.play().catch(() => undefined);
274|      }
275|    });
276|    const next = trackRef.current;
277|    if (!heard && next) requestPlayRef.current(next, 0);
278|  }
279|
280|  function changeVolume(value: number) {
281|    volumeRef.current = value;
282|    applyLevels();
283|    onVolumeChange(value);
284|  }
285|
286|  function toggleMute() {
287|    const next = !mutedRef.current;
288|    mutedRef.current = next;
289|    applyLevels();
290|    onMutedChange(next);
291|  }
292|
293|  const now = track ? nowPlaying(track) : null;
294|  const head = track
295|    ? [displayTitle(track.title), track.composer ?? track.artist]
296|        .filter((part): part is string => typeof part === "string" && part.length > 0)
297|        .join(" · ")
298|    : null;
