300|    !!track?.sourceUrl && !!track.artist && !!track.composer && track.artist !== track.composer;
301|
302|  return (
303|    <div className="player" role="region" aria-label="Music player" data-reduced-motion={reducedMotion}>
304|      <audio ref={firstRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(0, e.currentTarget)} onEnded={() => handleEnded(0)} />
305|      <audio ref={secondRef} preload="auto" onTimeUpdate={(e) => handleTimeUpdate(1, e.currentTarget)} onEnded={() => handleEnded(1)} />
