307|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
308|          <rect x="2.5" y="3" width="2" height="10" rx="0.5" />
309|          <path d="M13.5 3.5v9L6 8z" />
310|        </svg>
311|      </button>
312|      <button type="button" className="skip play" onClick={toggle} aria-label={playing ? "Pause" : "Play"} title={playing ? "Pause" : "Play"}>
313|        {playing ? (
314|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
315|            <rect x="4" y="3" width="2.6" height="10" rx="0.5" />
316|            <rect x="9.4" y="3" width="2.6" height="10" rx="0.5" />
317|          </svg>
318|        ) : (
319|          <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
320|            <path d="M5 3.5v9l7.5-4.5z" />
321|          </svg>
322|        )}
323|      </button>
324|      <button type="button" className="skip" onClick={onSkip} disabled={!canSkip} aria-label="Next track" title="Next track">
325|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
326|          <path d="M2.5 3.5v9l7.5-4.5z" />
327|          <rect x="11.5" y="3" width="2" height="10" rx="0.5" />
328|        </svg>
329|      </button>
330|      <button
331|        type="button"
332|        className="skip"
333|        onClick={toggleMute}
334|        aria-pressed={muted}
335|        aria-label={muted ? "Unmute" : "Mute"}
336|        title={muted ? "Unmute" : "Mute"}
337|      >
338|        <svg width="17" height="17" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
339|          <path d="M2.5 6v4h2.6L9 13V3L5.1 6H2.5z" />
340|          {muted ? (
341|            <path
342|              d="M11 6.5l4 4m0-4l-4 4"
343|              fill="none"
344|              stroke="currentColor"
345|              strokeWidth="1.5"
346|              strokeLinecap="round"
347|            />
348|          ) : (
349|            <path
350|              d="M11 5.6a3.4 3.4 0 0 1 0 4.8M12.8 3.8a6 6 0 0 1 0 8.4"
351|              fill="none"
352|              stroke="currentColor"
353|              strokeWidth="1.5"
354|              strokeLinecap="round"
355|            />
356|          )}
357|        </svg>
358|      </button>
359|      <label className="player-volume">
360|        <input
361|          type="range"
362|          min={0}
363|          max={1}
364|          step={0.05}
365|          value={volume}
366|          onChange={(e) => changeVolume(Number(e.target.value))}
367|          aria-label="Volume"
368|        />
369|      </label>
370|      <span className="player-track" aria-live="polite" title={now?.full}>
371|        {head ?? "The music is resting"}
372|        {showSource && track?.sourceUrl ? (
373|          <>
374|            {" · "}
375|            <a
376|              href={track.sourceUrl}
377|              rel="noopener noreferrer"
378|              target="_blank"
379|              aria-label={`${track.artist} (opens in new tab)`}
380|              title={`${track.artist} (opens in new tab)`}
381|            >
382|              {track.artist}{" "}
383|              <svg width="10" height="10" viewBox="0 0 12 12" aria-hidden="true">
384|                <path d="M3 9 9 3M4.5 3H9v4.5" />
385|              </svg>
386|            </a>
387|          </>
388|        ) : null}
389|      </span>
390|      <PlayerControls
391|        styles={styles}
392|        styleId={styleId}
393|        onStyleChange={onStyleChange}
394|        playlistLabel={playlistLabel}
